{"new_string":"import re


def parse_duration(text):
    """Return seconds for ordered h, m, s parts, or raise ValueError."""
    if not isinstance(text, str) or re.fullmatch(
        r"[0-9]+[hms](?: *[0-9]+[hms])*", text
    ) is None:
        raise ValueError("Invalid duration")

    seconds = 0
    previous_order = -1
    units = {"h": (0, 3600), "m": (1, 60), "s": (2, 1)}
    for number, unit in re.findall(r"([0-9]+)([hms])", text):
        order, multiplier = units[unit]
        if order <= previous_order:
            raise ValueError("Duration units must appear once, in h, m, s order")
        seconds += int(number) * multiplier
        previous_order = order
    return seconds
